      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Jian-Wei Pan",
        "Nicolas Gisin"
      ],
      "assessment": {
        "nobel_worthiness": "Long-distance quantum communication turned quantum-optical entanglement from a laboratory phenomenon into a functioning large-scale capability.",
        "attribution": "Gisin made seminal advances in practical quantum communication, while Pan led landmark long-distance entanglement and satellite-scale demonstrations.",
        "maturity": "The experimental record is extensive and the methods have become central to an international quantum-network effort.",
        "uncertainties": [
          "The field has many indispensable contributors, making a sharply bounded attribution difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals established control of light by engineered periodic structure and enabled a large body of nanophotonic science.",
        "attribution": "John and Yablonovitch supplied seminal physical concepts, while Joannopoulos provided influential theoretical foundations and design tools.",
        "maturity": "The effects have been repeatedly demonstrated in many materials systems and incorporated into optical devices.",
        "uncertainties": [
          "Applications are diffuse, so the prize-worthy core should be framed as the physical discovery rather than a single device."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical motion has brought macroscopic resonators into a regime where quantum measurement and control are experimentally tangible.",
        "attribution": "The credited researchers made complementary landmark contributions in microwave and optical optomechanical platforms.",
        "maturity": "Ground-state cooling, coherent control, and quantum-limited measurement have been reproduced across several platforms.",
        "uncertainties": [
          "The most fundamental single discovery within this broad experimental program is harder to isolate than for a mature instrument principle."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics created a controllable solid-state implementation of strong light-matter coupling and a powerful quantum-information platform.",
        "attribution": "Blais developed key theoretical architecture, and Wallraff and Schoelkopf led defining experimental demonstrations.",
        "maturity": "The platform is highly reproducible and underpins much present superconducting-circuit research.",
        "uncertainties": [
          "Its ultimate standing may depend on whether current quantum-computing promise becomes sustained scientific and technological impact."
        ]
      }
    },
